import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class PrettyPrintVisitorTest {

    @Mock
    private Printer printer;

    @Test
    public void visitAssignExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("x = 5");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitAssignExpr(new AssigningExpr("x", 5));
        assertEquals("x = 5", result);
    }

    @Test
    public void visitBinaryExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("(x + 1) * 2");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitBinaryExpr(new BinaryExpression("x", "+", 1, 2));
        assertEquals("(x + 1) * 2", result);
    }

    @Test
    public void visitUnaryExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("!x");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitUnaryExpr(new UnaryExpression("x", "!"));
        assertEquals("!x", result);
    }

    @Test
    public void visitConstExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("5");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitConstExpr(new Value(5));
        assertEquals("5", result);
    }

    @Test
    public void visitFunctionCallExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("func(x)");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitFunctionCallExpr(new FunctionCallExpression("x"));
        assertEquals("func(x)", result);
    }

    @Test
    public void visitPropertyPathExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("data.x");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitPropertyPathExpr(new PropertyPathExpression("x", "data"));
        assertEquals("data.x", result);
    }

    @Test
    public void visitAnonymousScriptExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("function(x) { return x * 2 }");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitAnonymousScriptExpr(new AnonymousScriptExpression("x", "return x * 2"));
        assertEquals("function(x) { return x * 2 }", result);
    }

    @Test
    public void visitFunctionScriptExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("def func(x): pass");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitFunctionScriptExpr(new FunctionScriptExpression("func", "x"));
        assertEquals("def func(x): pass", result);
    }

    @Test
    public void visitStatementSequenceScript_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("print('Hello, World!');");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitStatementSequenceScript(new StatementSequenceScriptExpression());
        assertEquals("print('Hello, World!');", result);
    }

    @Test
    public void visitVarExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("x");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitVarExpr(new VariableExpression("x"));
        assertEquals("x", result);
    }

    @Test
    public void visitProjectionExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("data.x");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitProjectionExpr(new ProjectionExpression("x", "data"));
        assertEquals("data.x", result);
    }

    @Test
    public void visitAliasExpr_ReturnsValidLine() {
        when(printer.print(anyString())).thenReturn("x as y");
        PrettyPrintVisitor visitor = new PrettyPrintVisitor(printer);
        String result = visitor.visitAliasExpr(new AliasExpression("x", "y"));
        assertEquals("x as y", result);
    }

    @Test
    public void visitVectorExpr_ReturnsValidLine() {
